with w as(select*from public.works where id in(149,162)) select jsonb_build_object('checked_at',clock_timestamp(),'project','qvplwejffhjvxaypmjut','works',(select jsonb_agg(to_jsonb(w)order by id)from w),'authors',(select jsonb_agg(to_jsonb(a)order by id)from public.authors a where id in(select author_id from w)),'editions',(select jsonb_agg(to_jsonb(e)order by id)from public.editions e where work_id in(select id from w)),'metadata',(select coalesce(jsonb_agg(to_jsonb(m)order by edition_id),'[]')from public.catalog_edition_metadata m where work_id in(select id from w)),'descriptions',(select coalesce(jsonb_agg(to_jsonb(d)order by work_id,language),'[]')from public.catalog_work_descriptions d where work_id in(select id from w)))as readback;